create or replace function public.admin_delete_account_v307(p_admin_session_token text,p_account_type text,p_account_id text) returns jsonb language plpgsql security definer set search_path=public,private,extensions,pg_temp as $$ declare v_admin_id text; v_type text:=lower(trim(coalesce(p_account_type,''))); v_id text:=trim(coalesce(p_account_id,'')); v_rows integer:=0; begin v_admin_id:=private.require_admin_session_v147(p_admin_session_token); if coalesce(v_admin_id,'')='' then return jsonb_build_object('ok',false,'error','INVALID_ADMIN_SESSION'); end if; if v_id='' then return jsonb_build_object('ok',false,'error','ACCOUNT_ID_REQUIRED'); end if; if v_type in ('employee','admin') then if v_id=v_admin_id then return jsonb_build_object('ok',false,'error','CANNOT_DELETE_CURRENT_ADMIN'); end if; delete from public.employees where id::text=v_id; elsif v_type='customer' then delete from public.customers where id::text=v_id; else return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACCOUNT_TYPE'); end if; get diagnostics v_rows=row_count; if v_rows=0 then return jsonb_build_object('ok',false,'error','ACCOUNT_NOT_FOUND'); end if; return jsonb_build_object('ok',true,'id',v_id,'account_type',v_type); end; $$;
revoke all on function public.admin_delete_account_v307 from public;
grant execute on function public.admin_delete_account_v307 to anon, authenticated;